import java.util.*;

class Solution {
    public int shipWithinDays(int[] weights, int days) {
        int lo = 0, hi = 0;
        for (int w : weights) { lo = Math.max(lo, w); hi += w; }
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (tripsNeeded(weights, mid) <= days) hi = mid; // limit is enough
            else lo = mid + 1;
        }
        return lo;
    }

    private int tripsNeeded(int[] weights, int limit) {
        int trips = 1, load = 0;
        for (int w : weights) {
            if (load + w > limit) { trips++; load = 0; } // start a new day
            load += w;
        }
        return trips;
    }
}

