class Solution:
    def shipWithinDays(self, weights: List[int], days: int) -> int:
        def trips(cap):
            t, cur = 1, 0
            for w in weights:
                if cur + w > cap: t, cur = t + 1, 0
                cur += w
            return t
        lo, hi = max(weights), sum(weights)
        while lo < hi:
            mid = (lo + hi) // 2
            if trips(mid) <= days: hi = mid
            else: lo = mid + 1
        return lo

