function shipWithinDays(weights, days) {
  let lo = 0, hi = 0;
  for (const w of weights) { lo = Math.max(lo, w); hi += w; }
  const need = (c) => { let t = 1, s = 0; for (const w of weights) { if (s + w > c) { t++; s = 0; } s += w; } return t; };
  while (lo < hi) { const m = (lo + hi) >> 1; if (need(m) <= days) hi = m; else lo = m + 1; }
  return lo;
}
